CREATE FUNCTION rf005_normalizar_municipio(nome TEXT)
RETURNS TEXT LANGUAGE SQL IMMUTABLE STRICT PARALLEL SAFE
RETURN regexp_replace(
    translate(lower(btrim(nome)), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc'),
    '[[:space:]]+', ' ', 'g'
);

ALTER TABLE regiao_atuacao ADD COLUMN municipio_codigo INTEGER REFERENCES municipio(codigo_ibge);

WITH correspondencias AS (
    SELECT uf, rf005_normalizar_municipio(nome) AS nome, min(codigo_ibge) AS codigo_ibge
    FROM municipio
    GROUP BY uf, rf005_normalizar_municipio(nome)
    HAVING count(*) = 1
)
UPDATE regiao_atuacao r
SET municipio_codigo = m.codigo_ibge
FROM correspondencias m
WHERE upper(r.estado) = m.uf AND rf005_normalizar_municipio(r.cidade) = m.nome;

CREATE INDEX regiao_atuacao_municipio_prestador_idx
    ON regiao_atuacao (municipio_codigo, id_prestador);

CREATE FUNCTION rf005_vincular_municipio()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.municipio_codigo IS NOT NULL THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.cidade = OLD.cidade AND NEW.estado = OLD.estado THEN
        RETURN NEW;
    END IF;
    SELECT CASE WHEN count(*) = 1 THEN min(m.codigo_ibge) END
    INTO NEW.municipio_codigo
    FROM municipio m
    WHERE m.uf = upper(NEW.estado)
      AND rf005_normalizar_municipio(m.nome) = rf005_normalizar_municipio(NEW.cidade);
    RETURN NEW;
END;
$$;

CREATE TRIGGER regiao_atuacao_vincular_municipio
    BEFORE INSERT OR UPDATE OF cidade, estado ON regiao_atuacao
    FOR EACH ROW EXECUTE FUNCTION rf005_vincular_municipio();
